/** @brief 提交键盘上的输入, 输入有效才退回主界面
 *  @note  键盘的"✓"把 LV_EVENT_READY 发给键盘对象, 而"回车"键是发给输入框的
 *         (见 lv_keyboard 的按键处理), 所以两处都要接上。 */
static void ui_keyboard_submit(void)
{
    if (GetInfo(NULL))
        xEventGroupSetBits(Task_Events(), EV_MAIN_SCREEN);
}

// event funtions
void ui_event_TextArea1(lv_event_t *e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if (event_code == LV_EVENT_FOCUSED)
    {
        _ui_keyboard_set_target(ui_Keyboard1, ui_TextArea1);
        _ui_flag_modify(ui_Keyboard1, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
    }
    if (event_code == LV_EVENT_DEFOCUSED)
    {
        _ui_flag_modify(ui_Keyboard1, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
    }
    if (event_code == LV_EVENT_READY)
    {
        ui_keyboard_submit();
    }
}

void ui_event_TextArea2(lv_event_t *e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if (event_code == LV_EVENT_FOCUSED)
    {
        _ui_keyboard_set_target(ui_Keyboard1, ui_TextArea2);
        _ui_flag_modify(ui_Keyboard1, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
    }
    if (event_code == LV_EVENT_DEFOCUSED)
    {
        _ui_flag_modify(ui_Keyboard1, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
    }
    if (event_code == LV_EVENT_READY)
    {
        ui_keyboard_submit();
    }
}

void ui_event_Keyboard1(lv_event_t *e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if (event_code == LV_EVENT_READY)
    {
        /* 键盘上的"确认": 提交输入, 再请 uiTask 退回主界面 */
        ui_keyboard_submit();
    }
}

void ui_event_Button1(lv_event_t *e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if (event_code == LV_EVENT_CLICKED)
    {
        /* 取消输入: 不提交任何内容, 直接退回主界面 */
        xEventGroupSetBits(Task_Events(), EV_MAIN_SCREEN);
    }
}

